        {"kind": "trace", "sql": "SELECT date_trunc('minute', time) m, count(*) c, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='ts-basic-service' AND attr_span_kind='Client' GROUP BY 1 ORDER BY 1", "claim": "Basic-service client-call errors appear only in 09:38-09:39, while the station pod is missing, then stop."},
        {"kind": "log", "sql": "SELECT time, service_name, level, attr_log_template FROM abnormal_logs WHERE service_name='ts-basic-service' AND level='SEVERE' ORDER BY time LIMIT 5", "claim": "Basic-service logs 'Connection refused' I/O errors from 09:38:39 to 09:39:42."}
