    {"from": "ts-travel2-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, s.service_name callee, count(*) c, sum(CASE WHEN s.attr_status_code='Error' THEN 1 ELSE 0 END) callee_errs FROM abnormal_traces s JOIN abnormal_traces p ON s.parent_span_id=p.span_id AND s.trace_id=p.trace_id WHERE s.attr_span_kind='Server' AND p.attr_span_kind='Client' AND s.service_name<>p.service_name AND p.service_name='ts-route-plan-service' GROUP BY 1,2", "claim": "Route-plan's calls into travel2-service fail with 21 errors in the abnormal window."}]},
